package android.content;import java.util.*;public class Context{public static final int RECEIVER_EXPORTED=2; public Context getApplicationContext(){return this;}public BroadcastReceiver registered;static final Map<String,Object> store=new HashMap<>(); public SharedPreferences getSharedPreferences(String k,int mode){return new SharedPreferences(){public boolean getBoolean(String k,boolean d){return store.containsKey(k)?(boolean)store.get(k):d;}public int getInt(String k,int d){return store.containsKey(k)?(int)store.get(k):d;}public String getString(String k,String d){return store.containsKey(k)?String.valueOf(store.get(k)):d;}public Editor edit(){return new Editor(){public Editor putBoolean(String k,boolean v){store.put(k,v);return this;}public Editor putInt(String k,int v){store.put(k,v);return this;}public Editor putString(String k,String v){store.put(k,v);return this;}public Editor remove(String k){store.remove(k);return this;}public void apply(){}};}};}public <T> T getSystemService(Class<T> clazz){try{return clazz.getDeclaredConstructor().newInstance();}catch(Exception e){throw new RuntimeException(e);}} public void registerReceiver(BroadcastReceiver r,IntentFilter f){if(registered==null)registered=r;}public void registerReceiver(BroadcastReceiver r,IntentFilter f,int flag){if(registered==null)registered=r;}public void unregisterReceiver(BroadcastReceiver r){} }